window.Catalog=window.Catalog||{};Catalog.setBadge=function(n){var t=document.getElementById("cartBadge");t&&(t.textContent=n)};Catalog.showToast=function(n){var t=document.getElementById("cartToast"),i=document.getElementById("cartToastText"),r;t&&(i&&(i.textContent=n),window.bootstrap&&bootstrap.Toast&&(r=new bootstrap.Toast(t,{delay:3e3}),r.show()))};Catalog.searchActive=!1;document.addEventListener("DOMContentLoaded",async function(){try{const n=await fetch("/Catalog/GetCartCount");if(!n.ok)throw new Error("HTTP "+n.status);const t=await n.json();Catalog.setBadge(t.count>0?t.count:0)}catch(n){console.error("Не удалось получить количество товаров:",n)}});